42	export async function styleWithItem(itemId: string): Promise<StyleResult> {
43	  try {
44	    const supabase = await createClient();
45	    const {
46	      data: { user },
47	    } = await supabase.auth.getUser();
48	    if (!user) return { status: "error", message: "Not signed in" };
49	
50	    const { data: profile } = await supabase
51	      .from("profiles")
52	      .select(
53	        "archetype, formality_min, formality_max, occasions, location_lat, location_lon, location_label, location_source, location_timezone",
54	      )
55	      .eq("id", user.id)
56	      .single();
57	
58	    const { data: itemsRaw } = await supabase
59	      .from("items")
60	      .select("*")
61	      .eq("user_id", user.id)
62	      .eq("archived", false);
63	    const items = itemsRaw ?? [];
64	    const subject = items.find((i) => i.id === itemId);
65	    if (!subject) return { status: "error", message: "Piece not found" };
66	
67	    // Fragrance occupies no slot in a look, so there is nothing to build around.
68	    if (subject.category === "Fragrance") {
69	      return { status: "empty", message: "Fragrance finishes a look rather than forming one." };
70	    }
71	
72	    const now = new Date();
73	    // The date key comes from the PROFILE timezone, not the forecast's, so the
74	    // cache can be checked without a network call — the same zone `toggleWear`
75	    // and `predictDefaultOccasion` use.
76	    const today = localDateFor(now, profile?.location_timezone ?? "UTC");
77	
78	    // THE CACHE. Checked before the quota is touched and before any I/O beyond
79	    // this one indexed lookup — re-opening an answer you already have must never
80	    // cost anything.
81	    const cached = await loadStyledLook(user.id, itemId, today);
82	    if (cached) return { status: "ok", outfitId: cached };
83	
84	    try {
85	      await assertCanGenerate(user.id);
86	    } catch (e) {
87	      if (e instanceof QuotaExceededError) return { status: "limited" };
88	      throw e;
89	    }
90	
91	    const loc = resolveLocation({ profile });
92	    const f = await fetchForecast(loc.lat, loc.lon);
93	    const advice = laterAdvice(f.hourly);
94	    const weather: WeatherPayload = {
95	      tempC: f.tempC,
96	      feelsLikeC: f.feelsLikeC,
97	      condition: f.condition,
98	      cityLabel: loc.label,
99	      timezone: f.timezone,
100	      locationOrigin: loc.origin,
101	      laterSentence: advice.sentence,
102	      adviceClause: advice.adviceClause,
103	      laterLabel: "Later",
104	      hourly: f.hourly,
105	    };
106	
107	    // The occasion the app already believes you are dressing for today — the CTA
108	    // has no picker, and a look styled for the wrong context is worse than one
109	    // that simply agrees with the rest of the day.
110	    const occasion = predictOccasion(now, f.timezone, profile?.occasions ?? []);
111	
112	    /**
113	     * Pinning, done BEFORE candidate building rather than after.
114	     *
115	     * Dropping every rival in the subject's own category means any combo using
116	     * that category uses THIS piece. Filtering the built list instead would have
117	     * to survive the 200-combo CAP, and a piece that never made the cut would
118	     * silently produce "no looks" — the same class of bug as the coverage
119	     * defect fixed in PR #14.
120	     */
121	    const pool = items.filter((i) => i.category !== subject.category || i.id === itemId);
122	    const candItems: CandidateItem[] = pool.map((i) => ({
123	      id: i.id,
124	      colors: i.colors ?? [],
125	      category: i.category,
126	      formality: i.formality,
127	      seasons: i.seasons ?? [],
128	      material: i.material,
129	    }));
130	
131	    const args = {
132	      weather: { tempC: f.tempC, rain: f.hourly.some((h) => h.isNow && h.rain) },
133	      season: currentSeason(now),
134	      excludeItemIds: [],
135	      maxAccessories: 1,
136	    };
137	    const aesthetic = profile?.archetype ? [profile.archetype] : [];
138	
139	    // Try the day's own formality band first, then the full scale. A piece
140	    // dressier or more casual than today's context is still stylable — refusing
141	    // would be the "hard filter empties a required slot" trap again.
142	    let pinned: ReturnType<typeof rankTopN> = [];
143	    for (const band of [personalBand(occasion, profile), [1, 5] as [number, number]]) {
